using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF9 breaking change: HasData() no longer accepts navigation/entity instances
        // with dynamically-evaluated values like DateTime.UtcNow (evaluated once at migration time).
        // Use a fixed seed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF9 breaking-change fixes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        // Replace with actual connection values
        options.UseCosmos("AccountEndpoint=https://localhost:8081/;AccountKey=...",
                          "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF9 BREAKING CHANGE #1: Cosmos DB discriminator property renamed from
        // "Discriminator" to "$type". Existing documents still use "Discriminator",
        // so we must explicitly configure the old property name to avoid mismatches.
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasDiscriminator<string>("Discriminator")
             .HasValue<Product>("Product");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
}

// EF9 BREAKING CHANGE #2: Synchronous I/O on Cosmos DB is no longer supported.
// All queries/saves must use async methods (ToListAsync, SaveChangesAsync, etc.).
class CosmosQueryService
{
    // WRONG in EF9 (throws InvalidOperationException):
    // var items = db.Products.ToList();

    // CORRECT — use async:
    public async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
    {
        return await db.Products.ToListAsync();
    }

    public async Task SaveProductAsync(CosmosDbContext db, Product product)
    {
        db.Products.Add(product);
        await db.SaveChangesAsync();
    }
}

